'use strict';

// MAIN //

/**
* Computes the cross product of two input strided arrays and assigns the results to an output strided array.
*
* @private
* @param {Object} x - first input array object
* @param {Collection} x.data - first input array data
* @param {Array<Function>} x.accessors - array element accessors
* @param {integer} strideX - stride length for `x`
* @param {NonNegativeInteger} offsetX - starting index for `x`
* @param {Object} y - second input array object
* @param {Collection} y.data - second input array data
* @param {Array<Function>} y.accessors - array element accessors
* @param {integer} strideY - stride length for `y`
* @param {NonNegativeInteger} offsetY - starting index for `y`
* @param {Object} z - output array object
* @param {Collection} z.data - output array data
* @param {Array<Function>} z.accessors - array element accessors
* @param {integer} strideZ - stride length for `z`
* @param {NonNegativeInteger} offsetZ - starting index for `z`
* @returns {Object} output array object
*
* @example
* var toAccessorArray = require( '@stdlib/array/base/to-accessor-array' );
* var arraylike2object = require( '@stdlib/array/base/arraylike2object' );
*
* var x = [ 1.0, 2.0, 3.0 ];
* var y = [ 4.0, 5.0, 6.0 ];
* var z = [ 0.0, 0.0, 0.0 ];
*
* gcross( arraylike2object( toAccessorArray( x ) ), 1, 0, arraylike2object( toAccessorArray( y ) ), 1, 0, arraylike2object( toAccessorArray( z ) ), 1, 0 );
* // z => [ -3.0, 6.0, -3.0 ]
*/
function gcross( x, strideX, offsetX, y, strideY, offsetY, z, strideZ, offsetZ ) {
	var xbuf;
	var ybuf;
	var zbuf;
	var xget;
	var yget;
	var zset;
	var x0;
	var x1;
	var x2;
	var y0;
	var y1;
	var y2;

	// Cache references to array data:
	xbuf = x.data;
	ybuf = y.data;
	zbuf = z.data;

	// Cache references to element accessors:
	xget = x.accessors[ 0 ];
	yget = y.accessors[ 0 ];
	zset = z.accessors[ 1 ];

	x0 = xget( xbuf, offsetX );
	x1 = xget( xbuf, offsetX+strideX );
	x2 = xget( xbuf, offsetX+(2*strideX) );
	y0 = yget( ybuf, offsetY );
	y1 = yget( ybuf, offsetY+strideY );
	y2 = yget( ybuf, offsetY+(2*strideY) );

	zset( zbuf, offsetZ, (x1*y2) - (x2*y1) );
	zset( zbuf, offsetZ+strideZ, (x2*y0) - (x0*y2) );
	zset( zbuf, offsetZ+(2*strideZ), (x0*y1) - (x1*y0) );

	return z;
}


// EXPORTS //

module.exports = gcross;
